// ShardingSphere 配置
@Bean
public DataSource shardingDataSource() {
    ShardingRuleConfiguration shardingRuleConfig = new ShardingRuleConfiguration();

    // 订单表分片规则
    TableRuleConfiguration orderRuleConfig = new TableRuleConfiguration("orders", "ds${0..1}.orders_${0..3}");

    // 分库策略：user_id % 2
    orderRuleConfig.setDatabaseShardingStrategyConfig(
        new InlineShardingStrategyConfiguration("user_id", "ds${user_id % 2}")
    );

    // 分表策略：user_id % 4
    orderRuleConfig.setTableShardingStrategyConfig(
        new InlineShardingStrategyConfiguration("user_id", "orders_${user_id % 4}")
    );

    shardingRuleConfig.getTableRuleConfigs().add(orderRuleConfig);

    return ShardingDataSourceFactory.createDataSource(
        createDataSourceMap(),
        shardingRuleConfig,
        new Properties()
    );
}

P5：架构升级

// 使用 Elasticsearch 处理复杂查询
public List<Order> search(OrderSearchRequest request) {
    SearchRequest searchRequest = new SearchRequest("orders");
    SearchSourceBuilder builder = new SearchSourceBuilder();

    // 构建查询条件
    BoolQueryBuilder boolQuery = QueryBuilders.boolQuery();
    if (request.getUserId() != null) {
        boolQuery.must(QueryBuilders.termQuery("user_id", request.getUserId()));
    }
    if (request.getStartTime() != null && request.getEndTime() != null) {
        boolQuery.must(QueryBuilders.rangeQuery("create_time")
            .gte(request.getStartTime())
            .lte(request.getEndTime()));
    }

    builder.query(boolQuery);
    builder.from((request.getPageNum() - 1) * request.getPageSize());
    builder.size(request.getPageSize());

    searchRequest.source(builder);

    SearchResponse response = restHighLevelClient.search(searchRequest, RequestOptions.DEFAULT);
    return parseResponse(response);
}

