// 缓存热点数据
@Service
public class OrderService {

    @Autowired
    private RedisTemplate<String, Object> redisTemplate;

    @Autowired
    private OrderMapper orderMapper;

    @Cacheable(value = "orders", key = "#userId", unless = "#result == null || #result.isEmpty()")
    public List<Order> selectByUserId(Long userId) {
        return orderMapper.selectByUserId(userId);
    }

    // 缓存预热
    @PostConstruct
    public void warmUpCache() {
        List<Long> hotUserIds = getHotUserIds();
        hotUserIds.forEach(userId -> {
            List<Order> orders = orderMapper.selectByUserId(userId);
            String cacheKey = "orders:user:" + userId;
            redisTemplate.opsForValue().set(cacheKey, orders, 5, TimeUnit.MINUTES);
        });
    }

    private List<Long> getHotUserIds() {
        // 查询最近 7 天活跃用户
        return orderMapper.selectActiveUsers(LocalDateTime.now().minusDays(7));
    }
}

