@Service
public class OrderSearchService {

    @Autowired
    private RestHighLevelClient restHighLevelClient;

    public List<Order> search(OrderSearchRequest request) throws IOException {
        SearchRequest searchRequest = new SearchRequest("orders");
        SearchSourceBuilder builder = new SearchSourceBuilder();

        // 构建查询条件
        BoolQueryBuilder boolQuery = QueryBuilders.boolQuery();

        if (request.getUserId() != null) {
            boolQuery.must(QueryBuilders.termQuery("user_id", request.getUserId()));
        }

        if (request.getStatus() != null) {
            boolQuery.must(QueryBuilders.termQuery("status", request.getStatus()));
        }

        if (request.getStartTime() != null && request.getEndTime() != null) {
            boolQuery.must(QueryBuilders.rangeQuery("create_time")
                .gte(request.getStartTime())
                .lte(request.getEndTime()));
        }

        if (request.getKeyword() != null) {
            boolQuery.must(QueryBuilders.multiMatchQuery(
                request.getKeyword(),
                "remark", "ext_data"
            ));
        }

        builder.query(boolQuery);

        // 分页
        builder.from((request.getPageNum() - 1) * request.getPageSize());
        builder.size(request.getPageSize());

        // 排序
        if ("create_time".equals(request.getSortField())) {
            builder.sort("create_time", SortOrder.DESC);
        }

        searchRequest.source(builder);

        // 执行查询
        SearchResponse response = restHighLevelClient.search(searchRequest, RequestOptions.DEFAULT);

        // 解析结果
        return parseResponse(response);
    }
}

