```text
@Service
public class InventoryService {

    @Autowired
    private InventoryRepository inventoryRepository;

    @Autowired
    private SagaLogRepository sagaLogRepository;

    @Autowired
    private RocketMQTemplate rocketMQTemplate;

    @RocketMQMessageListener(
        topic = "order-created-topic",
        consumerGroup = "inventory-consumer-group"
    )
    public class OrderCreatedListener implements RocketMQListener<OrderCreatedEvent> {

        @Override
        public void onMessage(OrderCreatedEvent event) {
            try {
                // 1. 扣减库存
                transactionTemplate.execute(status -> {
                    for (OrderItem item : event.getItems()) {
                        inventoryRepository.decrease(
                            item.getProductId(), 
                            item.getQuantity()
                        );
                    }
                    return null;
                });

                // 2. 记录 Saga 日志
                sagaLogRepository.save(new SagaLog(
                    event.getOrderId(), 
                    "INVENTORY_RESERVED", 
                    JSON.toJSONString(event.getItems())
                ));

                // 3. 发布库存预留事件
                rocketMQTemplate.convertAndSend(
                    "inventory-reserved-topic", 
                    new InventoryReservedEvent(event.getOrderId(), event.getItems())
                );

            } catch (InsufficientStockException e) {
                // 库存不足，发布失败事件
                rocketMQTemplate.convertAndSend(
                    "inventory-failed-topic", 
                    new InventoryFailedEvent(event.getOrderId(), e.getMessage())
                );
            }
        }
    }

    @RocketMQMessageListener(
        topic = "payment-failed-topic",
        consumerGroup = "inventory-consumer-group"
    )
    public class PaymentFailedListener implements RocketMQListener<PaymentFailedEvent> {

        @Override
        public void onMessage(PaymentFailedEvent event) {
            // 补偿：回滚库存
            SagaLog log = sagaLogRepository.findByOrderIdAndOperation(
                event.getOrderId(), 
                "INVENTORY_RESERVED"
            );
            List<OrderItem> items = JSON.parseArray(log.getContent(), OrderItem.class);

            transactionTemplate.execute(status -> {
                for (OrderItem item : items) {
                    inventoryRepository.increase(
                        item.getProductId(), 
                        item.getQuantity()
                    );
                }
                return null;
            });

            // 发布库存释放事件
            rocketMQTemplate.convertAndSend(
                "inventory-released-topic", 
                new InventoryReleasedEvent(event.getOrderId())
            );
        }
    }
}
