- RocketMQ Topic 迁移

双写双读方案完整流程：

```text
// 步骤 1：生产端双写
public class DualWriteProducer {
    private DefaultMQProducer oldProducer;
    private DefaultMQProducer newProducer;

    public void send(Message msg) throws Exception {
        // 旧集群写入（同步）
        SendResult oldResult = oldProducer.send(msg);

        // 新集群写入（异步）
        newProducer.send(msg, new SendCallback() {
            @Override
            public void onSuccess(SendResult sendResult) {
                // 记录双写成功
                log.info("Dual write success: msgId={}", sendResult.getMsgId());
            }

            @Override
            public void onException(Throwable e) {
                // 新集群写入失败，降级到旧集群
                log.error("New cluster write failed, fallback to old", e);
            }
        });
    }
}

// 步骤 2：消费端双读（新优先）
public class DualReadConsumer {
    private DefaultMQPushConsumer oldConsumer;
    private DefaultMQPushConsumer newConsumer;
    private Set<String> processedMsgIds = new ConcurrentHashMap<>();

    public void init() {
        // 新集群消费（主）
        newConsumer.subscribe("order-topic", "*");
        newConsumer.registerMessageListener((MessageListenerConcurrently) (msgs, context) -> {
            for (MessageExt msg : msgs) {
                if (!processedMsgIds.contains(msg.getMsgId())) {
                    processMessage(msg);
                    processedMsgIds.add(msg.getMsgId());
                }
            }
            return ConsumeConcurrentlyStatus.CONSUME_SUCCESS;
        });

        // 旧集群消费（兜底）
        oldConsumer.subscribe("order-topic", "*");
        oldConsumer.registerMessageListener((MessageListenerConcurrently) (msgs, context) -> {
            for (MessageExt msg : msgs) {
                if (!processedMsgIds.contains(msg.getMsgId())) {
                    processMessage(msg);
                    processedMsgIds.add(msg.getMsgId());
                }
            }
            return ConsumeConcurrentlyStatus.CONSUME_SUCCESS;
        });
    }
}

// 步骤 3：灰度切流（配置中心控制）
public class TrafficSwitcher {
    private double newClusterRatio; // 0.0 -> 1.0

    public boolean shouldUseNewCluster(String businessKey) {
        // 根据业务 key 哈希 + 灰度比例决定
        int hash = Math.abs(businessKey.hashCode());
        return (hash % 100) < (newClusterRatio * 100);
    }
}

// 步骤 4：完成迁移
// 1. 灰度比例 0% -> 100%
// 2. 观察新集群消费 lag，确认无积压
