```text
// 对账任务
public class MessageReconciliationJob {
    public void reconcile() {
        // 步骤 1：获取旧集群消息列表
        List<MessageExt> oldMessages = queryMessagesFromOldCluster(
            "order-topic", 
            startTime, 
            endTime
        );

        // 步骤 2：获取新集群消息列表
        List<MessageExt> newMessages = queryMessagesFromNewCluster(
            "order-topic", 
            startTime, 
            endTime
        );

        // 步骤 3：比对消息 ID
        Set<String> oldMsgIds = oldMessages.stream()
            .map(MessageExt::getMsgId)
            .collect(Collectors.toSet());

        Set<String> newMsgIds = newMessages.stream()
            .map(MessageExt::getMsgId)
            .collect(Collectors.toSet());

        // 步骤 4：找出差异
        Set<String> missingInNew = Sets.difference(oldMsgIds, newMsgIds);
        Set<String> missingInOld = Sets.difference(newMsgIds, oldMsgIds);

        // 步骤 5：处理差异消息
        if (!missingInNew.isEmpty()) {
            log.error("Missing messages in new cluster: {}", missingInNew);
            // 补发到新集群
            republishToNewCluster(missingInNew);
        }
    }
}

// offset 校验
public class OffsetValidator {
    public void validateOffsets() {
        // 获取旧集群消费 offset
        Map<TopicPartition, Long> oldOffsets = getConsumerOffsets(
            oldConsumerGroup, 
            "order-topic"
        );

        // 获取新集群消费 offset
        Map<TopicPartition, Long> newOffsets = getConsumerOffsets(
            newConsumerGroup, 
            "order-topic"
        );

        // 比对进度
        oldOffsets.forEach((tp, oldOffset) -> {
            Long newOffset = newOffsets.get(tp);
            if (newOffset != null && Math.abs(oldOffset - newOffset) > 1000) {
                log.warn("Offset mismatch: topic={}, partition={}, old={}, new={}", 
                    tp.topic(), tp.partition(), oldOffset, newOffset);
            }
        });
    }
}
