重试日志检查：

```text
// 自定义重试策略
public class CustomRetryPolicy {
    private int maxRetries = 3;
    private long retryInterval = 1000; // 1 秒

    public void sendWithRetry(Message message) {
        int retryCount = 0;
        while (retryCount <= maxRetries) {
            try {
                SendResult result = producer.send(message);
                log.info("Send success: msgId={}, retryCount={}", 
                    result.getMsgId(), retryCount);
                return;
            } catch (Exception e) {
                retryCount++;
                log.warn("Send failed, retrying: msgId={}, retryCount={}, error={}", 
                    message.getMsgId(), retryCount, e.getMessage());

                if (retryCount > maxRetries) {
                    log.error("Send failed after max retries: msgId={}", message.getMsgId());
                    // 记录到失败表
                    recordSendFailure(message.getMsgId(), e.getMessage());
                    throw e;
                }

                Thread.sleep(retryInterval);
            }
        }
    }
}
```

