// 记录消费日志
public class MessageConsumer {
    public void onMessage(ConsumerRecord<String, String> record) {
        String msgId = record.key();
        long offset = record.offset();

        log.info("Consume start: msgId={}, offset={}", msgId, offset);

        try {
            // 处理消息
            processMessage(record.value());

            // 记录消费成功
            log.info("Consume success: msgId={}, offset={}", msgId, offset);
            recordConsumeSuccess(msgId, offset);

        } catch (Exception e) {
            // 记录消费失败
            log.error("Consume failed: msgId={}, offset={}", msgId, offset, e);
            recordConsumeFailure(msgId, offset, e.getMessage());
        }
    }
}

