# order-topic:3:1100
```

- 排查方法

检查 key 分布：

```text
// 分析 key 分布
public class KeyDistributionAnalyzer {
    public void analyzeKeyDistribution() {
        KafkaConsumer<String, String> consumer = new KafkaConsumer<>(consumerConfig);
        consumer.subscribe(Collections.singletonList("order-topic"));

        Map<String, Integer> keyCountMap = new HashMap<>();

        while (true) {
            ConsumerRecords<String, String> records = consumer.poll(Duration.ofMillis(1000));
            for (ConsumerRecord<String, String> record : records) {
                String key = record.key();
                keyCountMap.put(key, keyCountMap.getOrDefault(key, 0) + 1);
            }

            // 定期输出 key 分布
            if (System.currentTimeMillis() % 60000 == 0) {
                log.info("Key distribution: {}", keyCountMap);

                // 找出热点 key
                keyCountMap.entrySet().stream()
                    .sorted(Map.Entry.<String, Integer>comparingByValue().reversed())
                    .limit(10)
                    .forEach(entry -> 
                        log.info("Hot key: key={}, count={}", entry.getKey(), entry.getValue())
                    );
            }
        }
    }

    // 输出示例：
    // Hot key: key=iPhone15, count=50000
    // Hot key: key=MacBookPro, count=10000
    // Hot key: key=iPad, count=5000
}
```

