- 解决方案一：自定义分区策略，打散热点 key

Java 代码示例：

```text
// 自定义分区器
public class HotKeyPartitioner implements Partitioner {
    private Random random = new Random();

    // 热点 key 列表（可配置）
    private Set<String> hotKeys = new HashSet<>(Arrays.asList(
        "iPhone15", "MacBookPro", "iPad"
    ));

    @Override
    public int partition(String topic, Object key, byte[] keyBytes, 
                        Object value, byte[] valueBytes, Cluster cluster) {
        String keyStr = (String) key;

        // 如果是热点 key，随机分配到不同分区
        if (hotKeys.contains(keyStr)) {
            int partitionCount = cluster.partitionCountForTopic(topic);
            return random.nextInt(partitionCount);
        }

        // 非热点 key，使用默认的 hash 分区
        int partitionCount = cluster.partitionCountForTopic(topic);
        return Math.abs(keyStr.hashCode()) % partitionCount;
    }

    @Override
    public void close() {}

    @Override
    public void configure(Map<String, ?> configs) {
        // 可以从配置中读取热点 key 列表
        String hotKeysConfig = (String) configs.get("hot.keys");
        if (hotKeysConfig != null) {
            hotKeys = new HashSet<>(Arrays.asList(hotKeysConfig.split(",")));
        }
    }
}

// 配置分区器
Properties props = new Properties();
props.put("partitioner.class", "com.example.HotKeyPartitioner");
props.put("hot.keys", "iPhone15,MacBookPro,iPad");

KafkaProducer<String, String> producer = new KafkaProducer<>(props);
