- 解决方案三：本地队列二次分发

消费者内部再做负载均衡：

```text
// 主消费者
public class MainConsumer {
    private KafkaConsumer<String, String> kafkaConsumer;
    private ExecutorService executorService;
    private BlockingQueue<Message> localQueue;

    public void start() {
        kafkaConsumer = new KafkaConsumer<>(consumerConfig);
        kafkaConsumer.subscribe(Collections.singletonList("order-topic"));

        // 本地队列（内存队列）
        localQueue = new LinkedBlockingQueue<>(10000);

        // 线程池（本地消费者）
        executorService = Executors.newFixedThreadPool(10);

        // 启动本地消费者
        for (int i = 0; i < 10; i++) {
            executorService.submit(new LocalConsumer(localQueue));
        }

        // 主消费者：拉取消息，放入本地队列
        while (true) {
            ConsumerRecords<String, String> records = kafkaConsumer.poll(Duration.ofMillis(100));
            for (ConsumerRecord<String, String> record : records) {
                Message message = new Message(record.key(), record.value());
                localQueue.offer(message);
            }
        }
    }
}

// 本地消费者
public class LocalConsumer implements Runnable {
    private BlockingQueue<Message> queue;

    public LocalConsumer(BlockingQueue<Message> queue) {
        this.queue = queue;
    }

    @Override
    public void run() {
        while (true) {
            try {
                Message message = queue.take();
                processMessage(message);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                break;
            }
        }
    }
}

// 架构图：
// Kafka Topic (4 分区)
//   ↓
// Main Consumer (1 个)
//   ↓
// Local Queue (内存队列)
//   ↓
// Local Consumers (10 个线程)
```

