    public DeferredResult<TaskResult> executeTask(@PathVariable String taskId) {
        DeferredResult<TaskResult> result = new DeferredResult<>(30000L); // 30秒超时

        result.onTimeout(() -> {
            result.setErrorResult(TaskResult.error("Task timeout"));
